// Virtual Address Space Segments

// STACK Segment (Automatic storage)
int local_data = 5;
void* stack_addr = &local_data;

// HEAP Segment (Dynamic allocation)
int* heap_ptr = (int*)malloc(10 * sizeof(int));
void* heap_addr = heap_ptr;
free(heap_ptr);

// DATA Segment (Global initialized data)
static int global_var = 42;
void* data_addr = &global_var;

// TEXT Segment (Read-only executable code)
void sample_func() { /* ... */ }
void (*func_addr)() = sample_func;

// Pointers provide virtual addresses
// Actual physical mapping is managed by the OS/MMU
// Isolation prevents one process from accessing addresses in another's space.
